import { handleMediaRelease } from "./media-release.js";
import { handleScheduling } from "./scheduling.js";
import { handleMetaOAuth } from "./meta-oauth.js";
import { handleMetaWebhooks } from "./meta-webhooks.js";
import { handleAnalytics } from "./analytics.js";
import { handleBackups } from "./backups.js";
const SESSION_SECONDS=28800, RATE_WINDOW=900, RATE_MAX=5, PBKDF2_ITERATIONS=100000;
const enc=new TextEncoder();
const STATIC_ASSETS={"/":{"body":"<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"referrer\" content=\"no-referrer\">\n  <title>Nature Frontiers — Operator Console</title>\n  <link rel=\"stylesheet\" href=\"/styles.css\">\n  <script src=\"/app.js\" defer></script>\n</head>\n<body>\n  <main class=\"shell\">\n    <header class=\"masthead\">\n      <div class=\"brand-mark\" aria-hidden=\"true\">NF</div>\n      <div>\n        <p class=\"eyebrow\">PRIVATE OPERATIONS</p>\n        <h1>Nature Frontiers</h1>\n        <p class=\"muted\">Facebook &amp; Instagram control centre</p>\n      </div>\n    </header>\n\n    <section id=\"login-panel\" class=\"panel\" aria-labelledby=\"login-title\">\n      <h2 id=\"login-title\">Operator sign-in</h2>\n      <p class=\"muted\">Access is restricted to the configured owner account.</p>\n      <form id=\"login-form\" autocomplete=\"on\">\n        <label for=\"username\">Operator ID</label>\n        <input id=\"username\" name=\"username\" autocomplete=\"username\" required maxlength=\"80\">\n        <label for=\"password\">Password</label>\n        <input id=\"password\" name=\"password\" type=\"password\" autocomplete=\"current-password\" required maxlength=\"1024\">\n        <button id=\"login-button\" type=\"submit\">Sign in</button>\n        <p id=\"login-error\" class=\"error\" role=\"alert\" aria-live=\"polite\"></p>\n      </form>\n    </section>\n\n    <section id=\"dashboard-panel\" hidden aria-labelledby=\"dashboard-title\">\n      <div class=\"dashboard-heading\">\n        <div>\n          <p class=\"eyebrow\">AUTHENTICATED OPERATOR</p>\n          <h2 id=\"dashboard-title\">System status</h2>\n          <p id=\"operator-label\" class=\"muted\"></p>\n        </div>\n        <button id=\"logout-button\" class=\"secondary\" type=\"button\">Sign out</button>\n      </div>\n      <div id=\"system-alert\" class=\"notice\" role=\"status\">Publishing is disabled. The emergency stop remains active.</div>\n      <article class=\"panel\">\n        <h3>Emergency stop</h3>\n        <p id=\"emergency-stop-status\" role=\"status\">Checking persistent safety controls…</p>\n        <button id=\"emergency-stop-button\" class=\"secondary\" type=\"button\" disabled>Activate emergency stop</button>\n        <p class=\"muted\">The emergency stop is a one-way application latch. It cannot be disabled from this dashboard.</p>\n      </article>\n      <article class=\"panel content-panel\" id=\"campaign-panel\">\n        <h3>Campaign management</h3>\n        <p class=\"muted\">Create and maintain campaigns. New campaigns are non-commercial with no disclosure requirement by default. Campaigns are archived, never deleted.</p>\n        <form id=\"campaign-form\">\n          <input id=\"campaign-id\" type=\"hidden\">\n          <input id=\"campaign-version\" type=\"hidden\">\n          <label for=\"campaign-name\">Campaign name</label><input id=\"campaign-name\" maxlength=\"160\" required>\n          <label for=\"campaign-description\">Description</label><textarea id=\"campaign-description\" rows=\"3\" maxlength=\"2000\"></textarea>\n          <label for=\"campaign-status\">Status</label><select id=\"campaign-status\"><option value=\"draft\">Draft</option><option value=\"active\">Active</option><option value=\"archived\">Archived</option></select>\n          <div class=\"form-actions\"><button id=\"save-campaign\" type=\"submit\">Create campaign</button><button id=\"cancel-campaign-edit\" class=\"secondary\" type=\"button\" hidden>Cancel edit</button></div>\n          <p id=\"campaign-error\" class=\"error\" role=\"alert\" aria-live=\"polite\"></p>\n        </form>\n        <div class=\"content-list-heading\"><h3>Campaigns</h3><button id=\"refresh-campaigns\" class=\"secondary\" type=\"button\">Refresh</button></div>\n        <div id=\"campaign-list\" class=\"content-list\" aria-live=\"polite\"></div>\n      </article>\n      <article class=\"panel content-panel\">\n        <h3>Content workspace</h3>\n        <p class=\"muted\">Create and edit internal drafts. Rights, human approval and Meta identity remain separate release gates. Nothing is sent to Facebook or Instagram.</p>\n        <form id=\"content-form\">\n          <input id=\"content-id\" type=\"hidden\"><input id=\"expected-revision\" type=\"hidden\">\n          <label for=\"content-campaign\">Campaign</label><select id=\"content-campaign\"><option value=\"\">No campaign</option></select>\n          <label for=\"content-type\">Content format</label>\n          <select id=\"content-type\" required><option value=\"feed_post\">Feed post</option><option value=\"reel\">Reel</option></select>\n          <label for=\"content-caption\">Caption</label><textarea id=\"content-caption\" rows=\"4\" maxlength=\"5000\" required></textarea>\n          <label for=\"media-url\">HTTPS media URL</label><input id=\"media-url\" type=\"url\" placeholder=\"https://...\" required>\n          <label for=\"media-sha256\">Media SHA-256</label><input id=\"media-sha256\" pattern=\"[a-fA-F0-9]{64}\" minlength=\"64\" maxlength=\"64\" required>\n          <div class=\"form-actions\"><button id=\"save-content\" type=\"submit\">Save draft</button><button id=\"cancel-edit\" class=\"secondary\" type=\"button\" hidden>Cancel edit</button></div>\n          <p id=\"content-error\" class=\"error\" role=\"alert\" aria-live=\"polite\"></p>\n        </form>\n        <div class=\"content-list-heading\"><h3>Saved drafts</h3><button id=\"refresh-content\" class=\"secondary\" type=\"button\">Refresh</button></div>\n        <div id=\"content-list\" class=\"content-list\" aria-live=\"polite\"></div>\n      </article>\n      <article class=\"panel content-panel\" id=\"schedule-panel\">\n        <h3>Scheduling</h3>\n        <p class=\"muted\">Create internal held slots in Africa/Johannesburg time. Dispatch is hard-blocked; nothing is sent to Meta.</p>\n        <form id=\"schedule-form\">\n          <label for=\"schedule-content\">Saved draft</label><select id=\"schedule-content\" required><option value=\"\">Choose a draft</option></select>\n          <label for=\"schedule-platform\">Platform</label><select id=\"schedule-platform\"><option value=\"facebook\">Facebook</option><option value=\"instagram\">Instagram</option></select>\n          <label for=\"schedule-at\">Scheduled local time (Africa/Johannesburg)</label><input id=\"schedule-at\" type=\"datetime-local\" required>\n          <div class=\"form-actions\"><button id=\"save-schedule\" type=\"submit\">Save held schedule</button><button id=\"refresh-schedules\" class=\"secondary\" type=\"button\">Refresh</button></div>\n          <p id=\"schedule-error\" class=\"error\" role=\"alert\" aria-live=\"polite\"></p>\n        </form>\n        <div id=\"schedule-list\" class=\"content-list\" aria-live=\"polite\"></div>\n        <button id=\"dispatch-preview\" class=\"secondary\" type=\"button\">Preview dispatch blockers</button>\n        <p id=\"dispatch-preview-result\" class=\"muted\" role=\"status\"></p>\n      </article>\n      <article class=\"panel content-panel\" id=\"meta-connection-panel\">\n        <h3>Meta identity connection</h3>\n        <p class=\"muted\">Connect and verify the Nature Frontiers Facebook Page using Page permissions. Instagram uses a separate Instagram Login connection and remains unverified until that flow is completed. This does not enable publishing.</p>\n        <div class=\"form-actions\"><button id=\"connect-meta\" type=\"button\">Connect Meta account</button><button id=\"refresh-meta\" class=\"secondary\" type=\"button\">Refresh connections</button></div>\n        <p id=\"meta-connection-error\" class=\"error\" role=\"alert\" aria-live=\"polite\"></p>\n        <div id=\"meta-connection-list\" class=\"content-list\" aria-live=\"polite\"></div>\n      </article>\n      <article class=\"panel content-panel\" id=\"analytics-panel\">\n        <h3>Analytics</h3>\n        <p class=\"muted\">Read-only snapshots from verified Facebook and Instagram posts that have a confirmed remote media ID. Collection never publishes or modifies Meta content.</p>\n        <div class=\"form-actions\"><button id=\"collect-analytics\" type=\"button\">Collect metrics</button><button id=\"refresh-analytics\" class=\"secondary\" type=\"button\">Refresh reports</button></div>\n        <p id=\"analytics-error\" class=\"error\" role=\"alert\" aria-live=\"polite\"></p>\n        <div id=\"analytics-list\" class=\"content-list\" aria-live=\"polite\"></div>\n      </article>\n      <article class=\"panel content-panel\" id=\"backup-panel\">\n        <h3>Backup &amp; recovery</h3>\n        <p class=\"muted\">Encrypted snapshots are stored in a separate staging D1 database. Restore is merge-only (never deletes append-only history), creates a pre-restore backup, revokes sessions, holds schedules, un-verifies Meta identities, revokes release approvals and reactivates the emergency stop.</p>\n        <div class=\"form-actions\"><button id=\"create-backup\" type=\"button\">Create encrypted backup</button><button id=\"refresh-backups\" class=\"secondary\" type=\"button\">Refresh backups</button></div>\n        <p id=\"backup-error\" class=\"error\" role=\"alert\" aria-live=\"polite\"></p>\n        <div id=\"backup-list\" class=\"content-list\" aria-live=\"polite\"></div>\n      </article>\n      <div class=\"grid\">\n        <article class=\"panel\">\n          <h3>Facebook</h3>\n          <dl id=\"facebook-status\"></dl>\n        </article>\n        <article class=\"panel\">\n          <h3>Instagram</h3>\n          <dl id=\"instagram-status\"></dl>\n        </article>\n      </div>\n      <article class=\"panel\">\n        <h3>Application capabilities</h3>\n        <dl id=\"capability-status\"></dl>\n      </article>\n      <article class=\"panel\">\n        <div class=\"content-list-heading\"><h3>Audit history</h3><button id=\"refresh-audit\" class=\"secondary\" type=\"button\">Refresh</button></div>\n        <div id=\"audit-list\" class=\"content-list\" aria-live=\"polite\"></div>\n      </article>\n      <p class=\"footnote\">This console supports internal drafts, held scheduling, Meta identity verification, signed webhook receipt, read-only analytics and encrypted backup/merge restore. Provider dispatch and publishing remain disabled. Restore revokes sessions and release approvals, holds schedules, and requires explicit operator confirmation.</p>\n      <p id=\"dashboard-error\" class=\"error\" role=\"alert\" aria-live=\"polite\"></p>\n    </section>\n    <footer>Private operator workspace · Publishing disabled · Human approval and rights gates required</footer>\n  </main>\n</body>\n</html>\n","type":"text/html; charset=utf-8"},"/app.js":{"body":"const loginPanel = document.querySelector(\"#login-panel\");\nconst dashboardPanel = document.querySelector(\"#dashboard-panel\");\nconst loginForm = document.querySelector(\"#login-form\");\nconst loginError = document.querySelector(\"#login-error\");\nconst dashboardError = document.querySelector(\"#dashboard-error\");\nconst loginButton = document.querySelector(\"#login-button\");\nconst logoutButton = document.querySelector(\"#logout-button\");\nlet csrfToken = \"\";\n\nfunction addRows(target, values) {\n  target.replaceChildren();\n  for (const [key, value] of Object.entries(values)) {\n    const term = document.createElement(\"dt\");\n    const detail = document.createElement(\"dd\");\n    term.textContent = key.replaceAll(/([A-Z])/g, \" $1\").replaceAll(\"_\", \" \");\n    detail.textContent = typeof value === \"boolean\" ? (value ? \"Yes\" : \"No\") : String(value);\n    target.append(term, detail);\n  }\n}\n\nasync function api(path, options = {}) {\n  const response = await fetch(path, {\n    credentials: \"same-origin\",\n    cache: \"no-store\",\n    ...options,\n    headers: {\n      ...(options.headers ?? {}),\n      ...(options.body ? { \"Content-Type\": \"application/json\" } : {}),\n      ...(options.method && options.method !== \"GET\" && csrfToken ? { \"X-CSRF-Token\": csrfToken } : {})\n    }\n  });\n  if (response.status === 204) return null;\n  const body = await response.json().catch(() => ({}));\n  if (!response.ok) throw new Error(body.error || \"Request failed\");\n  return body;\n}\n\nasync function loadDashboard(user) {\n  loginPanel.hidden = true;\n  dashboardPanel.hidden = false;\n  document.querySelector(\"#operator-label\").textContent = user.id + \" · \" + user.role;\n  try {\n    const status = await api(\"/api/system/status\");\n    addRows(document.querySelector(\"#facebook-status\"), status.destinations.facebook);\n    addRows(document.querySelector(\"#instagram-status\"), status.destinations.instagram);\n    addRows(document.querySelector(\"#capability-status\"), status.capabilities);\n    await refreshCampaigns();\n    await refreshContent();\n    await refreshSchedules();\n    await refreshMetaConnections();\n    await refreshAnalytics();\n    await refreshBackups();\n    await refreshAudit();\n    await refreshControls();\n  } catch (error) {\n    dashboardError.textContent = error.message;\n  }\n}\n\nloginForm.addEventListener(\"submit\", async event => {\n  event.preventDefault();\n  loginError.textContent = \"\";\n  loginButton.disabled = true;\n  try {\n    const result = await api(\"/api/auth/login\", {\n      method: \"POST\",\n      body: JSON.stringify({\n        username: document.querySelector(\"#username\").value,\n        password: document.querySelector(\"#password\").value\n      })\n    });\n    csrfToken = result.csrfToken;\n    document.querySelector(\"#password\").value = \"\";\n    await loadDashboard(result.user);\n  } catch (error) {\n    loginError.textContent = error.message;\n  } finally {\n    loginButton.disabled = false;\n  }\n});\n\nlogoutButton.addEventListener(\"click\", async () => {\n  logoutButton.disabled = true;\n  try {\n    await api(\"/api/auth/logout\", {\n      method: \"POST\",\n      headers: { \"X-CSRF-Token\": csrfToken }\n    });\n    csrfToken = \"\";\n    dashboardPanel.hidden = true;\n    loginPanel.hidden = false;\n    loginForm.reset();\n  } catch (error) {\n    dashboardError.textContent = error.message;\n  } finally {\n    logoutButton.disabled = false;\n  }\n});\n\n\nconst contentForm = document.querySelector(\"#content-form\");\nconst contentError = document.querySelector(\"#content-error\");\nconst contentList = document.querySelector(\"#content-list\");\n\nconst campaignForm = document.querySelector(\"#campaign-form\");\nconst campaignList = document.querySelector(\"#campaign-list\");\nconst campaignError = document.querySelector(\"#campaign-error\");\n\nasync function refreshControls() {\n  const status = document.querySelector(\"#emergency-stop-status\");\n  const button = document.querySelector(\"#emergency-stop-button\");\n  if (!status || !button) return;\n  try {\n    const result = await api(\"/api/system/controls\");\n    const emergency = result.controls.find(control => control.key === \"emergency_stop\");\n    const publishing = result.controls.find(control => control.key === \"publishing_enabled\");\n    const dryRun = result.controls.find(control => control.key === \"dry_run\");\n    const active = Boolean(emergency?.enabled);\n    status.textContent = \"Emergency stop: \" + (active ? \"ACTIVE\" : \"INACTIVE\") +\n      \" · Publishing: \" + (publishing?.enabled ? \"enabled\" : \"disabled\") +\n      \" · Dry run: \" + (dryRun?.enabled ? \"enabled\" : \"disabled\");\n    button.disabled = active;\n  } catch (error) {\n    status.textContent = \"Safety controls unavailable: \" + error.message;\n    button.disabled = true;\n  }\n}\n\ndocument.querySelector(\"#emergency-stop-button\")?.addEventListener(\"click\", async event => {\n  const button = event.currentTarget;\n  button.disabled = true;\n  try {\n    await api(\"/api/system/emergency-stop\", {method:\"POST\",body:\"{}\"});\n    await refreshControls();\n  } catch (error) {\n    document.querySelector(\"#emergency-stop-status\").textContent = error.message;\n    button.disabled = false;\n  }\n});\n\n\nasync function refreshAudit() {\n  const list = document.querySelector(\"#audit-list\");\n  if (!list) return;\n  list.replaceChildren();\n  try {\n    const result = await api(\"/api/audit\");\n    if (!result.items.length) {\n      const empty = document.createElement(\"p\");\n      empty.className = \"muted\";\n      empty.textContent = \"No audit events recorded.\";\n      list.append(empty);\n      return;\n    }\n    for (const event of result.items) {\n      const row = document.createElement(\"article\");\n      row.className = \"content-item\";\n      const heading = document.createElement(\"h4\");\n      heading.textContent = event.event_type;\n      const detail = document.createElement(\"p\");\n      detail.textContent = event.actor + \" · \" + (event.content_id || \"system\") + \" · \" + event.created_at;\n      const payload = document.createElement(\"p\");\n      payload.className = \"muted\";\n      payload.textContent = event.details_json;\n      row.append(heading, detail, payload);\n      list.append(row);\n    }\n  } catch (error) {\n    dashboardError.textContent = error.message;\n  }\n}\n\n\nfunction resetCampaignForm() {\n  campaignForm.reset();\n  document.querySelector(\"#campaign-id\").value = \"\";\n  document.querySelector(\"#campaign-version\").value = \"\";\n  document.querySelector(\"#campaign-status\").value = \"draft\";\n  document.querySelector(\"#save-campaign\").textContent = \"Create campaign\";\n  document.querySelector(\"#cancel-campaign-edit\").hidden = true;\n}\n\nasync function refreshCampaigns() {\n  if (!campaignList) return;\n  try {\n    const result = await api(\"/api/campaigns\");\n    const selector = document.querySelector(\"#content-campaign\");\n    const selected = selector.value;\n    selector.replaceChildren(new Option(\"No campaign\", \"\"));\n    campaignList.replaceChildren();\n    for (const campaign of result.items) {\n      if (campaign.status !== \"archived\") selector.append(new Option(campaign.name, campaign.id));\n      const card = document.createElement(\"article\");\n      card.className = \"content-item\";\n      const heading = document.createElement(\"h4\");\n      heading.textContent = campaign.name;\n      const description = document.createElement(\"p\");\n      description.textContent = campaign.description || \"No description.\";\n      const meta = document.createElement(\"p\");\n      meta.className = \"muted\";\n      meta.textContent = campaign.status + \" · \" + campaign.content_count + \" content items · commercial \" + (campaign.commercial ? \"yes\" : \"no\") + \" · disclosure required \" + (campaign.disclosure_required ? \"yes\" : \"no\");\n      card.append(heading, description, meta);\n      if (campaign.status !== \"archived\") {\n        const edit = document.createElement(\"button\");\n        edit.type = \"button\";\n        edit.className = \"secondary\";\n        edit.textContent = \"Edit campaign\";\n        edit.addEventListener(\"click\", () => {\n          document.querySelector(\"#campaign-id\").value = campaign.id;\n          document.querySelector(\"#campaign-version\").value = campaign.version;\n          document.querySelector(\"#campaign-name\").value = campaign.name;\n          document.querySelector(\"#campaign-description\").value = campaign.description;\n          document.querySelector(\"#campaign-status\").value = campaign.status;\n          document.querySelector(\"#save-campaign\").textContent = \"Save campaign\";\n          document.querySelector(\"#cancel-campaign-edit\").hidden = false;\n          campaignForm.scrollIntoView({behavior:\"smooth\",block:\"start\"});\n        });\n        card.append(edit);\n      }\n      campaignList.append(card);\n    }\n    if (![...selector.options].some(option => option.value === selected)) selector.value = \"\";\n    else selector.value = selected;\n  } catch (error) {\n    campaignError.textContent = error.message;\n  }\n}\n\ncampaignForm?.addEventListener(\"submit\", async event => {\n  event.preventDefault();\n  campaignError.textContent = \"\";\n  const id = document.querySelector(\"#campaign-id\").value;\n  const payload = {\n    name: document.querySelector(\"#campaign-name\").value,\n    description: document.querySelector(\"#campaign-description\").value\n  };\n  if (id) {\n    payload.expectedVersion = Number(document.querySelector(\"#campaign-version\").value);\n    payload.status = document.querySelector(\"#campaign-status\").value;\n  }\n  const button = document.querySelector(\"#save-campaign\");\n  button.disabled = true;\n  try {\n    await api(id ? \"/api/campaigns/\" + encodeURIComponent(id) : \"/api/campaigns\", {\n      method: id ? \"PUT\" : \"POST\",\n      body: JSON.stringify(payload)\n    });\n    resetCampaignForm();\n    await refreshCampaigns();\n    await refreshContent();\n  } catch (error) {\n    campaignError.textContent = error.message;\n  } finally {\n    button.disabled = false;\n  }\n});\n\ndocument.querySelector(\"#cancel-campaign-edit\")?.addEventListener(\"click\", resetCampaignForm);\ndocument.querySelector(\"#refresh-campaigns\")?.addEventListener(\"click\", refreshCampaigns);\ndocument.querySelector(\"#refresh-audit\")?.addEventListener(\"click\", refreshAudit);\n\n\nfunction resetContentForm() {\n  contentForm.reset();\n  document.querySelector(\"#content-id\").value = \"\";\n  document.querySelector(\"#expected-revision\").value = \"\";\n  document.querySelector(\"#save-content\").textContent = \"Save draft\";\n  document.querySelector(\"#cancel-edit\").hidden = true;\n}\n\nasync function refreshContent() {\n  if (!contentList) return;\n  contentList.replaceChildren();\n  try {\n    const result = await api(\"/api/content\");\n    if (!result.items.length) {\n      const empty = document.createElement(\"p\");\n      empty.className = \"muted\";\n      empty.textContent = \"No drafts yet.\";\n      contentList.append(empty);\n      return;\n    }\n    for (const item of result.items) {\n      const card = document.createElement(\"article\");\n      card.className = \"content-item\";\n      const heading = document.createElement(\"h4\");\n      heading.textContent = item.content_type.replace(\"_\", \" \") + \" · revision \" + item.revision;\n      const caption = document.createElement(\"p\");\n      caption.textContent = item.caption;\n      const meta = document.createElement(\"p\");\n      meta.className = \"muted\";\n      meta.textContent = \"Draft · \" + item.id + (item.campaign_name ? \" · campaign \" + item.campaign_name : \"\") + \" · updated \" + item.updated_at;\n      const actions = document.createElement(\"div\");\n      actions.className = \"form-actions\";\n      const edit = document.createElement(\"button\");\n      edit.type = \"button\";\n      edit.className = \"secondary\";\n      edit.textContent = \"Edit\";\n      edit.addEventListener(\"click\", () => {\n        document.querySelector(\"#content-id\").value = item.id;\n        document.querySelector(\"#expected-revision\").value = item.revision;\n        document.querySelector(\"#content-campaign\").value = item.campaign_id || \"\";\n        document.querySelector(\"#content-type\").value = item.content_type;\n        document.querySelector(\"#content-caption\").value = item.caption;\n        document.querySelector(\"#media-url\").value = item.media_url;\n        document.querySelector(\"#media-sha256\").value = item.media_sha256;\n        document.querySelector(\"#save-content\").textContent = \"Save revision \" + (item.revision + 1);\n        document.querySelector(\"#cancel-edit\").hidden = false;\n        contentForm.scrollIntoView({ behavior: \"smooth\", block: \"start\" });\n      });\n      const history = document.createElement(\"button\");\n      history.type = \"button\";\n      history.className = \"secondary\";\n      history.textContent = \"Revision history\";\n      history.addEventListener(\"click\", async () => {\n        const old = card.querySelector(\".revision-history\");\n        if (old) { old.remove(); return; }\n        const data = await api(\"/api/content/\" + encodeURIComponent(item.id) + \"/history\");\n        const list = document.createElement(\"ol\");\n        list.className = \"revision-history\";\n        for (const revision of data.revisions) {\n          const row = document.createElement(\"li\");\n          row.textContent = \"r\" + revision.revision + \" · \" + revision.editor + \" · \" + revision.created_at + \" · \" + revision.payload_sha256;\n          list.append(row);\n        }\n        card.append(list);\n      });\n      const release = document.createElement(\"button\");\n      release.type = \"button\";\n      release.className = \"secondary\";\n      release.textContent = \"Release gates\";\n      release.addEventListener(\"click\", () => showReleaseStatus(card, item));\n      actions.append(edit, history, release);\n      card.append(heading, caption, meta, actions);\n      contentList.append(card);\n    }\n  } catch (error) {\n    contentError.textContent = error.message;\n  }\n}\n\ncontentForm?.addEventListener(\"submit\", async event => {\n  event.preventDefault();\n  contentError.textContent = \"\";\n  const id = document.querySelector(\"#content-id\").value;\n  const payload = {\n    campaignId: document.querySelector(\"#content-campaign\").value || null,\n    contentType: document.querySelector(\"#content-type\").value,\n    caption: document.querySelector(\"#content-caption\").value,\n    mediaUrl: document.querySelector(\"#media-url\").value,\n    mediaSha256: document.querySelector(\"#media-sha256\").value\n  };\n  if (id) payload.expectedRevision = Number(document.querySelector(\"#expected-revision\").value);\n  const button = document.querySelector(\"#save-content\");\n  button.disabled = true;\n  try {\n    await api(id ? \"/api/content/\" + encodeURIComponent(id) : \"/api/content\", {\n      method: id ? \"PUT\" : \"POST\",\n      body: JSON.stringify(payload)\n    });\n    resetContentForm();\n    await refreshContent();\n  } catch (error) {\n    contentError.textContent = error.message;\n  } finally {\n    button.disabled = false;\n  }\n});\n\ndocument.querySelector(\"#cancel-edit\")?.addEventListener(\"click\", resetContentForm);\ndocument.querySelector(\"#refresh-content\")?.addEventListener(\"click\", refreshContent);\n\n(async function restoreSession() {\n  try {\n    const session = await api(\"/api/auth/session\");\n    csrfToken = session.csrfToken;\n    await loadDashboard(session.user);\n  } catch {\n    loginPanel.hidden = false;\n    dashboardPanel.hidden = true;\n  }\n})();\n\nasync function showReleaseStatus(card, item) {\n  const existing = card.querySelector(\".release-status\");\n  if (existing) { existing.remove(); return; }\n  try {\n    const result = await api(\"/api/content/\" + encodeURIComponent(item.id) + \"/release-status\");\n    const panel = document.createElement(\"div\");\n    panel.className = \"release-status\";\n    const heading = document.createElement(\"h5\");\n    heading.textContent = \"Release gates\";\n    const rows = [\n      [\"Media validation\", result.media.validationStatus],\n      [\"Rights evidence\", result.rights.length ? result.rights.map(x => x.rights_status + (x.revoked_at ? \" (revoked)\" : \"\")).join(\", \") : \"MISSING\"],\n      [\"Current approvals\", result.approvals.filter(x => x.currentPayload && x.decision === \"approved\" && !x.revoked_at).map(x => x.platform).join(\", \") || \"NONE\"]\n    ];\n    panel.append(heading);\n    for (const [label, value] of rows) {\n      const line = document.createElement(\"p\");\n      line.textContent = label + \": \" + value;\n      panel.append(line);\n    }\n    const rightsHeading = document.createElement(\"h5\");\n    rightsHeading.textContent = \"Rights evidence records\";\n    panel.append(rightsHeading);\n    for (const evidence of result.rights) {\n      const entry = document.createElement(\"div\");\n      entry.className = \"content-item\";\n      const detail = document.createElement(\"p\");\n      detail.textContent = evidence.rights_holder + \" · \" + evidence.rights_status + \" · \" + evidence.evidence_sha256 + (evidence.revoked_at ? \" · REVOKED\" : \"\");\n      entry.append(detail);\n      if (!evidence.revoked_at) {\n        const revoke = document.createElement(\"button\");\n        revoke.type = \"button\";\n        revoke.className = \"secondary\";\n        revoke.textContent = \"Revoke rights evidence\";\n        revoke.addEventListener(\"click\", async () => {\n          revoke.disabled = true;\n          try {\n            const outcome = await api(\"/api/content/\" + encodeURIComponent(item.id) + \"/rights/\" + encodeURIComponent(evidence.id) + \"/revoke\", {method:\"POST\",body:JSON.stringify({confirmation:\"REVOKE RIGHTS EVIDENCE\"})});\n            detail.textContent += \" · REVOKED by \" + outcome.revokedBy;\n            revoke.remove();\n          } catch (error) {\n            resultLine.textContent = error.message;\n            revoke.disabled = false;\n          }\n        });\n        entry.append(revoke);\n      }\n      panel.append(entry);\n    }\n    const note = document.createElement(\"p\");\n    note.className = \"muted\";\n    note.textContent = \"This is a read-only gate summary. No rights are inferred and no publishing action is available.\";\n    panel.append(note);\n    const workflow = document.createElement(\"section\");\n    workflow.className = \"release-workflow\";\n    workflow.innerHTML = `\n      <h5>Media and rights workflow</h5>\n      <p class=\"muted\">Step 1 fetches the configured HTTPS media URL and hashes the actual bytes. Configure the allowed media/evidence hosts in Worker secrets before use.</p>\n      <button type=\"button\" class=\"secondary\" data-action=\"verify-media\">Verify media bytes</button>\n      <form data-action=\"record-rights\">\n        <h5>Step 2 · Rights evidence and owner attestation</h5>\n        <label>Rights status<select name=\"rightsStatus\" required><option value=\"owned\">Owned / original</option><option value=\"licensed\">Licensed</option><option value=\"public_domain\">Public domain</option><option value=\"unverified\">Unverified / needs evidence</option><option value=\"rejected\">Rejected / not permitted</option></select></label>\n        <label>Rights holder<input name=\"rightsHolder\" required maxlength=\"200\"></label>\n        <label>Original source URL<input name=\"sourceUrl\" type=\"url\" required></label>\n        <label>License / ownership reference<input name=\"licenseReference\" required maxlength=\"500\"></label>\n        <label>Evidence HTTPS URL<input name=\"evidenceUrl\" type=\"url\" required></label>\n        <label>Evidence file SHA-256<input name=\"evidenceSha256\" pattern=\"[a-fA-F0-9]{64}\" minlength=\"64\" maxlength=\"64\" required></label>\n        <label>Rights expiry (optional)<input name=\"expiresAt\" type=\"datetime-local\"></label>\n        <fieldset><legend>Permitted platforms</legend><label><input type=\"checkbox\" name=\"platform\" value=\"facebook\"> Facebook</label><label><input type=\"checkbox\" name=\"platform\" value=\"instagram\"> Instagram</label></fieldset>\n        <fieldset><legend>Permitted uses</legend><label><input type=\"checkbox\" name=\"permittedUse\" value=\"social_media\" required> Social media (required)</label><label><input type=\"checkbox\" name=\"permittedUse\" value=\"editorial\"> Editorial</label><label><input type=\"checkbox\" name=\"permittedUse\" value=\"commercial\"> Commercial</label></fieldset>\n        <label><input type=\"checkbox\" name=\"attest\" required> I confirm these rights details are accurate and I have authority to attest.</label>\n        <button type=\"submit\">Verify evidence and record rights</button>\n      </form>\n      <form data-action=\"approve-content\">\n        <h5>Step 3 · Human approval</h5>\n        <label>Platform<select name=\"platform\" required><option value=\"facebook\">Facebook</option><option value=\"instagram\">Instagram</option></select></label>\n        <label>Rights evidence SHA-256<input name=\"rightsEvidenceSha256\" pattern=\"[a-fA-F0-9]{64}\" minlength=\"64\" maxlength=\"64\" required></label>\n        <label>Approval expiry (optional)<input name=\"expiresAt\" type=\"datetime-local\"></label>\n        <label><input type=\"checkbox\" name=\"confirm\" required> I reviewed this exact current draft revision and approve it for the selected platform.</label>\n        <button type=\"submit\">Sign human approval receipt</button>\n      </form>\n      <button type=\"button\" class=\"secondary\" data-action=\"verify-approval\">Verify approval receipt</button>\n      <p class=\"muted\" data-workflow-result role=\"status\"></p>`;\n    const resultLine = workflow.querySelector(\"[data-workflow-result]\");\n    workflow.querySelector(\"[data-action='verify-media']\").addEventListener(\"click\", async event => {\n      const trigger = event.currentTarget;\n      trigger.disabled = true;\n      try {\n        const result = await api(\"/api/content/\" + encodeURIComponent(item.id) + \"/media/verify\", {method:\"POST\",body:\"{}\"});\n        resultLine.textContent = \"Media passed: \" + result.sha256 + \" · \" + result.byteLength + \" bytes · \" + result.mimeType;\n      } catch (error) { resultLine.textContent = error.message; }\n      finally { trigger.disabled = false; }\n    });\n    workflow.querySelector(\"[data-action='record-rights']\").addEventListener(\"submit\", async event => {\n      event.preventDefault();\n      const form = event.currentTarget, data = new FormData(form);\n      const platforms = data.getAll(\"platform\");\n      const permittedUses = data.getAll(\"permittedUse\");\n      const payload = {rightsStatus:data.get(\"rightsStatus\"),rightsHolder:data.get(\"rightsHolder\"),sourceUrl:data.get(\"sourceUrl\"),licenseReference:data.get(\"licenseReference\"),evidenceUrl:data.get(\"evidenceUrl\"),evidenceSha256:data.get(\"evidenceSha256\"),expiresAt:data.get(\"expiresAt\") ? new Date(data.get(\"expiresAt\")).toISOString() : null,permittedPlatforms:platforms,permittedUses,confirmation:\"I CONFIRM THESE RIGHTS DETAILS ARE ACCURATE\"};\n      try {\n        const result = await api(\"/api/content/\" + encodeURIComponent(item.id) + \"/rights\", {method:\"POST\",body:JSON.stringify(payload)});\n        resultLine.textContent = \"Rights evidence recorded: \" + result.evidenceSha256 + \". \" + result.warning;\n        form.reset();\n      } catch (error) { resultLine.textContent = error.message; }\n    });\n    workflow.querySelector(\"[data-action='verify-approval']\").addEventListener(\"click\", async event => {\n      const trigger = event.currentTarget;\n      trigger.disabled = true;\n      try {\n        const result = await api(\"/api/content/\" + encodeURIComponent(item.id) + \"/approval-verification\");\n        resultLine.textContent = result.receipts.length ? result.receipts.map(x => x.platform + \": signature \" + (x.signatureValid ? \"valid\" : \"INVALID\") + \", binding \" + (x.bindingValid ? \"valid\" : \"INVALID\") + \", current revision \" + (x.currentPayload ? \"yes\" : \"no\") + \", revoked \" + (x.revoked ? \"yes\" : \"no\") + \", expired \" + (x.expired ? \"yes\" : \"no\")).join(\" · \") : \"No approval receipts recorded.\";\n      } catch (error) { resultLine.textContent = error.message; }\n      finally { trigger.disabled = false; }\n    });\n    workflow.querySelector(\"[data-action='approve-content']\").addEventListener(\"submit\", async event => {\n      event.preventDefault();\n      const form = event.currentTarget, data = new FormData(form), platform = data.get(\"platform\");\n      const payload = {platform,rightsEvidenceSha256:data.get(\"rightsEvidenceSha256\"),expiresAt:data.get(\"expiresAt\") ? new Date(data.get(\"expiresAt\")).toISOString() : null,confirmation:\"APPROVE CURRENT REVISION FOR \" + platform.toUpperCase()};\n      try {\n        const result = await api(\"/api/content/\" + encodeURIComponent(item.id) + \"/approval\", {method:\"POST\",body:JSON.stringify(payload)});\n        resultLine.textContent = \"Signed approval recorded for \" + result.platform + \" · revision \" + result.revision + \" · receipt \" + result.approvalId;\n        form.reset();\n        await refreshContent();\n      } catch (error) { resultLine.textContent = error.message; }\n    });\n    panel.append(workflow);\n    card.append(panel);\n  } catch (error) {\n    contentError.textContent = error.message;\n  }\n}\n\n\nconst scheduleForm=document.querySelector(\"#schedule-form\");\nconst scheduleList=document.querySelector(\"#schedule-list\");\nconst scheduleError=document.querySelector(\"#schedule-error\");\nasync function refreshSchedules(){\n if(!scheduleList)return;\n scheduleList.replaceChildren();\n try{\n  const [result,content]=await Promise.all([api(\"/api/schedules\"),api(\"/api/content\")]);\n  const selector=document.querySelector(\"#schedule-content\"),selected=selector.value;\n  selector.replaceChildren(new Option(\"Choose a draft\",\"\"));\n  for(const item of content.items)if([\"draft\",\"needs_review\"].includes(item.status))selector.append(new Option(item.content_type.replace(\"_\",\" \")+\" · \"+item.caption.slice(0,70),item.id));\n  if([...selector.options].some(x=>x.value===selected))selector.value=selected;\n  if(!result.items.length){const empty=document.createElement(\"p\");empty.className=\"muted\";empty.textContent=\"No held schedule slots yet.\";scheduleList.append(empty);return;}\n  for(const item of result.items){\n   const card=document.createElement(\"article\");card.className=\"content-item\";\n   const title=document.createElement(\"h4\");title.textContent=item.platform+\" · \"+item.state;\n   const detail=document.createElement(\"p\");detail.textContent=item.content_type+\" · \"+item.scheduled_at+\" · \"+item.timezone;\n   const note=document.createElement(\"p\");note.className=\"muted\";note.textContent=\"Internal held slot. Provider dispatch is disabled.\";\n   card.append(title,detail,note);\n   if(item.state===\"held\"||item.state===\"ready\"||item.state===\"failed\"||item.state===\"dead_letter\"){\n    const cancel=document.createElement(\"button\");cancel.type=\"button\";cancel.className=\"secondary\";cancel.textContent=\"Cancel held slot\";\n    cancel.addEventListener(\"click\",async()=>{cancel.disabled=true;try{await api(\"/api/schedules/\"+encodeURIComponent(item.id)+\"/cancel\",{method:\"POST\",body:\"{}\"});await refreshSchedules();}catch(error){scheduleError.textContent=error.message;cancel.disabled=false;}});\n    card.append(cancel);\n   }\n   scheduleList.append(card);\n  }\n }catch(error){scheduleError.textContent=error.message;}\n}\nscheduleForm?.addEventListener(\"submit\",async event=>{\n event.preventDefault();scheduleError.textContent=\"\";\n const value=document.querySelector(\"#schedule-at\").value;\n const date=new Date(value+\":00+02:00\");\n if(!value||!Number.isFinite(date.getTime())){scheduleError.textContent=\"Choose a valid Johannesburg local date and time.\";return;}\n const button=document.querySelector(\"#save-schedule\");button.disabled=true;\n try{\n  await api(\"/api/schedules\",{method:\"POST\",body:JSON.stringify({contentId:document.querySelector(\"#schedule-content\").value,platform:document.querySelector(\"#schedule-platform\").value,scheduledAt:date.toISOString()})});\n  scheduleForm.reset();await refreshSchedules();\n }catch(error){scheduleError.textContent=error.message;}finally{button.disabled=false;}\n});\ndocument.querySelector(\"#refresh-schedules\")?.addEventListener(\"click\",refreshSchedules);\ndocument.querySelector(\"#dispatch-preview\")?.addEventListener(\"click\",async()=>{\n const target=document.querySelector(\"#dispatch-preview-result\");target.textContent=\"Checking dispatch blockers…\";\n try{\n  const response=await fetch(\"/api/schedules/dispatch-preview\",{method:\"POST\",credentials:\"same-origin\",headers:{\"Content-Type\":\"application/json\",\"X-CSRF-Token\":csrfToken},body:\"{}\"});\n  const body=await response.json().catch(()=>({}));\n  target.textContent=(body.blockers||[body.error||\"Dispatch remains blocked.\"]).join(\" · \");\n }catch(error){target.textContent=error.message;}\n});\nasync function refreshMetaConnections(){\n const list=document.querySelector(\"#meta-connection-list\");if(!list)return;list.replaceChildren();\n const errorNode=document.querySelector(\"#meta-connection-error\");\n try{\n  const result=await api(\"/api/meta/connections\");\n  if(!result.items.length){const empty=document.createElement(\"p\");empty.className=\"muted\";empty.textContent=\"No Meta Pages connected.\";list.append(empty);return;}\n  for(const item of result.items){\n   const card=document.createElement(\"article\");card.className=\"content-item\";\n   const title=document.createElement(\"h4\");title.textContent=item.pageName+\" · \"+item.status;\n   const page=document.createElement(\"p\");page.textContent=\"Facebook Page ID: \"+item.pageId+\" · identity \"+(item.facebookIdentityVerified?\"verified\":\"not verified\");\n   const ig=document.createElement(\"p\");ig.textContent=\"Instagram: \"+(item.instagramAccountId||\"not linked\")+\" · identity \"+(item.instagramIdentityVerified?\"verified\":\"not verified\");\n   const perms=document.createElement(\"p\");perms.className=\"muted\";perms.textContent=\"Granted permissions: \"+item.grantedPermissions.join(\", \");\n   card.append(title,page,ig,perms);\n   if(!item.facebookIdentityVerified){\n    const verify=document.createElement(\"button\");verify.type=\"button\";verify.textContent=\"Verify this Facebook Page\";verify.addEventListener(\"click\",async()=>{\n     verify.disabled=true;\n     try{await api(\"/api/meta/connections/\"+encodeURIComponent(item.id)+\"/verify\",{method:\"POST\",body:JSON.stringify({confirmation:\"VERIFY NATURE FRONTIERS PAGE\",expectedPageId:item.pageId})});await refreshMetaConnections();const status=await api(\"/api/system/status\");addRows(document.querySelector(\"#facebook-status\"),status.destinations.facebook);addRows(document.querySelector(\"#instagram-status\"),status.destinations.instagram);}\n     catch(error){errorNode.textContent=error.message;verify.disabled=false;}\n    });card.append(verify);\n   }\n   list.append(card);\n  }\n }catch(error){errorNode.textContent=error.message;}\n}\ndocument.querySelector(\"#connect-meta\")?.addEventListener(\"click\",async event=>{\n const button=event.currentTarget,errorNode=document.querySelector(\"#meta-connection-error\");button.disabled=true;errorNode.textContent=\"\";\n try{const result=await api(\"/api/meta/oauth/start\",{method:\"POST\",body:JSON.stringify({confirmation:\"START META ACCOUNT CONNECTION\"})});window.location.assign(result.authorizationUrl);}\n catch(error){errorNode.textContent=error.message;button.disabled=false;}\n});\ndocument.querySelector(\"#refresh-meta\")?.addEventListener(\"click\",refreshMetaConnections);\nif(new URLSearchParams(location.search).get(\"meta\")===\"connected\"){\n const node=document.querySelector(\"#meta-connection-error\");if(node)node.textContent=\"Meta authorization completed. Select the exact Nature Frontiers Page and verify it below.\";\n}\n\n\nasync function refreshAnalytics(){\n const list=document.querySelector(\"#analytics-list\");if(!list)return;list.replaceChildren();\n const errorNode=document.querySelector(\"#analytics-error\");\n try{\n  const result=await api(\"/api/analytics\");\n  if(!result.items.length){const empty=document.createElement(\"p\");empty.className=\"muted\";empty.textContent=\"No analytics snapshots yet. Verified published posts with remote IDs are required.\";list.append(empty);return;}\n  for(const item of result.items){\n   const card=document.createElement(\"article\");card.className=\"content-item\";\n   const title=document.createElement(\"h4\");title.textContent=item.platform+\" · \"+item.content_type+\" · \"+item.collected_at;\n   const caption=document.createElement(\"p\");caption.textContent=item.caption||\"\";\n   const metrics=document.createElement(\"p\");metrics.textContent=JSON.stringify(JSON.parse(item.metrics_json));\n   const source=document.createElement(\"p\");source.className=\"muted\";source.textContent=\"Source Graph API \"+item.source_api_version+\" · content \"+item.content_id;\n   card.append(title,caption,metrics,source);list.append(card);\n  }\n }catch(error){errorNode.textContent=error.message;}\n}\ndocument.querySelector(\"#refresh-analytics\")?.addEventListener(\"click\",refreshAnalytics);\ndocument.querySelector(\"#collect-analytics\")?.addEventListener(\"click\",async event=>{\n const button=event.currentTarget,errorNode=document.querySelector(\"#analytics-error\");button.disabled=true;errorNode.textContent=\"\";\n try{const result=await api(\"/api/analytics/collect\",{method:\"POST\",body:\"{}\"});errorNode.textContent=\"Collected \"+result.collected+\" snapshots; failed \"+result.failed+\".\";await refreshAnalytics();}\n catch(error){errorNode.textContent=error.message;}finally{button.disabled=false;}\n});\n\n\nasync function refreshBackups(){\n const list=document.querySelector(\"#backup-list\");if(!list)return;list.replaceChildren();\n const errorNode=document.querySelector(\"#backup-error\");\n try{\n  const result=await api(\"/api/backups\");\n  if(!result.items.length){const empty=document.createElement(\"p\");empty.className=\"muted\";empty.textContent=\"No encrypted backups yet.\";list.append(empty);return;}\n  for(const item of result.items){\n   const card=document.createElement(\"article\");card.className=\"content-item\";\n   const title=document.createElement(\"h4\");title.textContent=item.created_at+\" · \"+item.status;\n   const detail=document.createElement(\"p\");detail.textContent=\"Backup \"+item.backup_id+\" · \"+item.schema_version+\" · \"+item.ciphertext_bytes+\" encrypted bytes · \"+item.chunk_count+\" chunks\";\n   const hash=document.createElement(\"p\");hash.className=\"muted\";hash.textContent=\"SHA-256: \"+item.sha256;\n   const actions=document.createElement(\"div\");actions.className=\"form-actions\";\n   const verify=document.createElement(\"button\");verify.type=\"button\";verify.className=\"secondary\";verify.textContent=\"Verify integrity\";\n   verify.addEventListener(\"click\",async()=>{verify.disabled=true;try{const check=await api(\"/api/backups/verify\",{method:\"POST\",body:JSON.stringify({backupId:item.backup_id,expectedSha256:item.sha256})});errorNode.textContent=\"Verified backup \"+check.backupId+\" · \"+check.byteLength+\" bytes · \"+check.sha256;}catch(error){errorNode.textContent=error.message;}finally{verify.disabled=false;}});\n   const restore=document.createElement(\"button\");restore.type=\"button\";restore.className=\"secondary\";restore.textContent=\"Restore (merge)\";\n   restore.addEventListener(\"click\",async()=>{\n    const confirmation=window.prompt(\"This creates a pre-restore backup, merges missing records, revokes active sessions and release approvals, holds schedules, and un-verifies Meta identities. Type exactly: RESTORE STAGING FROM VERIFIED BACKUP\");\n    if(confirmation!==\"RESTORE STAGING FROM VERIFIED BACKUP\")return;\n    restore.disabled=true;\n    try{const result=await api(\"/api/backups/restore\",{method:\"POST\",body:JSON.stringify({confirmation,backupId:item.backup_id,expectedSha256:item.sha256})});errorNode.textContent=\"Restore completed. Pre-restore backup: \"+result.preRestoreBackupId+\". The operator session was revoked; signing in again…\";setTimeout(()=>window.location.assign(\"/\"),1200);}\n    catch(error){errorNode.textContent=error.message;restore.disabled=false;}\n   });\n   actions.append(verify,restore);card.append(title,detail,hash,actions);list.append(card);\n  }\n }catch(error){errorNode.textContent=error.message;}\n}\ndocument.querySelector(\"#refresh-backups\")?.addEventListener(\"click\",refreshBackups);\ndocument.querySelector(\"#create-backup\")?.addEventListener(\"click\",async event=>{\n const button=event.currentTarget,errorNode=document.querySelector(\"#backup-error\");\n if(!window.confirm(\"Create an encrypted staging backup in the separate backup database?\"))return;\n button.disabled=true;errorNode.textContent=\"\";\n try{const result=await api(\"/api/backups\",{method:\"POST\",body:JSON.stringify({confirmation:\"CREATE ENCRYPTED STAGING BACKUP\"})});errorNode.textContent=\"Encrypted backup verified: \"+result.backupId+\" · SHA-256 \"+result.sha256;await refreshBackups();}\n catch(error){errorNode.textContent=error.message;}finally{button.disabled=false;}\n});\n","type":"text/javascript; charset=utf-8"},"/styles.css":{"body":":root {\n  color-scheme: light;\n  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n  color: #17221d;\n  background: #f3f6f2;\n  font-synthesis: none;\n}\n* { box-sizing: border-box; }\nbody { margin: 0; min-height: 100vh; }\n.shell { width: min(920px, calc(100% - 32px)); margin: 0 auto; padding: 48px 0 28px; }\n.masthead { display: flex; align-items: center; gap: 18px; margin-bottom: 32px; }\n.brand-mark { display: grid; place-items: center; width: 54px; height: 54px; border-radius: 16px; background: #173f31; color: #fff; font-weight: 800; letter-spacing: .04em; }\n.eyebrow { margin: 0 0 6px; color: #557466; font-size: .72rem; font-weight: 800; letter-spacing: .14em; }\nh1 { margin: 0; font-size: clamp(1.8rem, 5vw, 2.5rem); letter-spacing: -.04em; }\nh2 { margin: 0 0 8px; font-size: 1.35rem; }\nh3 { margin: 0 0 16px; font-size: 1.05rem; }\n.muted { color: #66756d; margin: 6px 0 0; }\n.panel { background: #fff; border: 1px solid #dfe7e1; border-radius: 16px; padding: 24px; box-shadow: 0 8px 28px rgb(24 55 39 / 5%); }\n#login-panel { max-width: 460px; }\nform { display: grid; gap: 10px; margin-top: 22px; }\nlabel { font-size: .88rem; font-weight: 700; }\ninput { width: 100%; border: 1px solid #cbd7cf; border-radius: 9px; padding: 12px 13px; font: inherit; margin-bottom: 8px; }\ninput:focus { outline: 3px solid #c8e4d3; border-color: #327450; }\nbutton { border: 0; border-radius: 9px; padding: 12px 18px; background: #1d5b3e; color: white; font: inherit; font-weight: 700; cursor: pointer; }\nbutton:disabled { opacity: .55; cursor: wait; }\nbutton.secondary { background: #e8eee9; color: #254536; }\n.dashboard-heading { display: flex; justify-content: space-between; align-items: center; gap: 16px; margin: 0 0 20px; }\n.notice { padding: 14px 16px; border: 1px solid #e7d7a8; border-radius: 10px; background: #fff8e5; color: #614c19; margin-bottom: 18px; font-weight: 650; }\n.grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; margin-bottom: 16px; }\ndl { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 10px 16px; margin: 0; font-size: .9rem; }\ndt { color: #617168; }\ndd { margin: 0; text-align: right; font-weight: 700; overflow-wrap: anywhere; }\n.footnote, footer { color: #718078; font-size: .82rem; line-height: 1.5; }\n.footnote { margin: 18px 2px; }\nfooter { margin-top: 28px; text-align: center; }\n.error { min-height: 1.3em; color: #a12c2c; font-size: .88rem; }\n[hidden] { display: none !important; }\n@media (max-width: 620px) {\n  .shell { padding-top: 28px; }\n  .grid { grid-template-columns: 1fr; }\n  .dashboard-heading { align-items: flex-start; }\n  .panel { padding: 19px; }\n}\n\n.content-panel { margin: 0 0 18px; }\n.content-panel form { max-width: 720px; }\ntextarea, select { width: 100%; border: 1px solid #cbd7cf; border-radius: 9px; padding: 12px 13px; font: inherit; background: white; }\ntextarea:focus, select:focus { outline: 3px solid #c8e4d3; border-color: #327450; }\n.form-actions, .content-list-heading { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; }\n.content-list-heading { justify-content: space-between; margin-top: 28px; }\n.content-list-heading h3 { margin: 0; }\n.content-list { display: grid; gap: 12px; margin-top: 14px; }\n.content-item { border: 1px solid #dfe7e1; border-radius: 12px; padding: 16px; overflow-wrap: anywhere; }\n.content-item h4 { margin: 0 0 8px; text-transform: capitalize; }\n.content-item p { line-height: 1.5; }\n.revision-history { padding-left: 24px; font-size: .82rem; overflow-wrap: anywhere; }\n.revision-history li { margin: 8px 0; }\n","type":"text/css; charset=utf-8"}};
const json=(v,s=200,h={})=>{const x=new Headers(h);x.set("Content-Type","application/json; charset=utf-8");x.set("Cache-Control","no-store");x.set("X-Content-Type-Options","nosniff");x.set("X-Frame-Options","DENY");x.set("Referrer-Policy","no-referrer");x.set("Content-Security-Policy","default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; connect-src 'self'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'");return new Response(v===null?null:JSON.stringify(v),{status:s,headers:x});};
const hex=b=>[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,"0")).join("");
